import { describe, expect, it, vi } from 'vitest';
import { resolveSearchConfig } from '@/lib/search/config';
import {
  registerSearchProvider,
  resolveSearchProvider,
  type SearchProvider,
} from '@/lib/search/provider';

describe('search configuration', () => {
  it('uses the local provider by default', () => {
    expect(resolveSearchConfig(undefined)).toEqual({
      enabled: true,
      prompt: 'Search...',
      position: 'header',
      provider: 'local',
      options: {},
      shortcut: 'k',
      shortcutLabel: 'Ctrl K',
    });
  });

  it('resolves supported search positions and falls back to the header', () => {
    expect(resolveSearchConfig({ position: 'sidebar' }).position).toBe('sidebar');

    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    expect(resolveSearchConfig({ position: 'footer' as unknown as 'header' }).position).toBe(
      'header',
    );
    expect(warn).toHaveBeenCalledOnce();
    warn.mockRestore();

    expect(resolveSearchConfig(false).position).toBe('header');
  });

  it('normalizes configured values', () => {
    const options = { applicationId: 'test' };

    expect(resolveSearchConfig({ prompt: ' Search docs ', provider: ' Hosted ', options })).toEqual(
      {
        enabled: true,
        prompt: 'Search docs',
        position: 'header',
        provider: 'hosted',
        options,
        shortcut: 'k',
        shortcutLabel: 'Ctrl K',
      },
    );
  });

  it('can disable search', () => {
    expect(resolveSearchConfig(false).enabled).toBe(false);
  });

  it('can configure or disable the keyboard shortcut', () => {
    expect(resolveSearchConfig({ shortcut: 's', shortcutLabel: 'Ctrl S' })).toMatchObject({
      shortcut: 's',
      shortcutLabel: 'Ctrl S',
    });
    expect(resolveSearchConfig({ shortcut: false }).shortcut).toBe(false);
  });
});

describe('search providers', () => {
  it('registers and resolves a custom provider with its options', async () => {
    const provider: SearchProvider = {
      async search(query) {
        return [{ url: '/custom', page: query, snippet: 'Custom result', score: 1 }];
      },
    };
    let receivedOptions: Record<string, unknown> | undefined;
    const unregister = registerSearchProvider('test-provider', options => {
      receivedOptions = options;
      return provider;
    });

    try {
      const resolved = await resolveSearchProvider('TEST-PROVIDER', { index: 'docs' });

      expect(resolved).toMatchObject({ providerId: 'test-provider', fellBack: false });
      expect(receivedOptions).toEqual({ index: 'docs' });
      expect(await resolved.provider.search('hello')).toEqual([
        { url: '/custom', page: 'hello', snippet: 'Custom result', score: 1 },
      ]);
    } finally {
      unregister();
    }
  });

  it('falls back to local for an unknown provider', async () => {
    const resolved = await resolveSearchProvider('missing-provider');

    expect(resolved).toMatchObject({ providerId: 'local', fellBack: true });
  });

  it('does not allow replacing the built-in providers', () => {
    expect(() => registerSearchProvider('local', () => ({ search: async () => [] }))).toThrow(
      'cannot replace',
    );
    expect(() => registerSearchProvider('pagefind', () => ({ search: async () => [] }))).toThrow(
      'cannot replace',
    );
  });

  it('resolves the built-in pagefind provider', async () => {
    const resolved = await resolveSearchProvider('Pagefind');

    expect(resolved).toMatchObject({ providerId: 'pagefind', fellBack: false });
  });

  it('pagefind falls back to local search when the bundle cannot load', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});

    try {
      const resolved = await resolveSearchProvider('pagefind');

      // In this environment the pagefind bundle import rejects, so the
      // provider must delegate to local (stub index -> empty results).
      expect(await resolved.provider.search('anything')).toEqual([]);
      expect(warn).toHaveBeenCalledOnce();
    } finally {
      warn.mockRestore();
    }
  });
});

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';
import { ApiPlayground, proxiedUrl } from '@/components/ApiPlayground';
import type { NormalizedOperation } from '@/lib/types';

const operation: NormalizedOperation = {
  id: 'list-orders',
  key: 'GET /orders',
  method: 'GET',
  path: '/orders',
  tags: ['Orders'],
  parameters: {
    query: [
      { name: 'status', type: 'enum<string>', enum: ['pending', 'shipped'], example: 'pending' },
      { name: 'limit', type: 'integer', required: true, example: '20' },
      { name: 'archived', type: 'boolean' },
    ],
    path: [],
    header: [],
    cookie: [{ name: 'session', type: 'string' }],
  },
  responses: [],
  security: [
    { name: 'basic', type: 'http', scheme: 'basic', label: 'basic (http basic)' },
    { name: 'key', type: 'apiKey', in: 'header', paramName: 'X-API-Key', label: 'key (apiKey)' },
  ],
  servers: [
    { url: 'https://api.demo.dev', description: 'Production' },
    { url: 'https://sandbox.demo.dev', description: 'Sandbox' },
  ],
  serverUrl: 'https://api.demo.dev',
  samples: [],
};

describe('ApiPlayground', () => {
  const html = renderToStaticMarkup(<ApiPlayground operation={operation} />);

  it('offers every server as a suggestion', () => {
    expect(html).toContain('<datalist');
    expect(html).toContain('value="https://sandbox.demo.dev"');
  });

  it('renders inputs for each security scheme', () => {
    expect(html).toContain('Username');
    expect(html).toContain('Password');
    expect(html).toContain('X-API-Key');
    expect((html.match(/type="password"/g) || []).length).toBe(2);
  });

  it('renders enum and boolean parameters as selects and marks required ones', () => {
    expect(html).toContain('<option value="pending"');
    expect(html).toContain('<option value="true"');
    expect(html).toContain('value="20"');
    expect(html).toContain('>required<');
    expect(html).toContain('Cookie parameters cannot be set');
  });

  it('omits the body for GET operations and previews the request', () => {
    expect(html).not.toContain('<textarea');
    // The cURL preview sits in a collapsed section; only its trigger is in the static markup.
    expect(html).toContain('>Request</button>');
    expect(html).toContain('Send a request to see the response.');
  });
});

describe('proxiedUrl', () => {
  it('substitutes or appends the encoded target', () => {
    expect(proxiedUrl('https://a.dev/x?y=1')).toBe('https://a.dev/x?y=1');
    expect(proxiedUrl('https://a.dev/x?y=1', 'https://p.dev/?url=$url')).toBe(
      'https://p.dev/?url=https%3A%2F%2Fa.dev%2Fx%3Fy%3D1',
    );
    expect(proxiedUrl('https://a.dev/x', 'https://p.dev/')).toBe(
      'https://p.dev/https%3A%2F%2Fa.dev%2Fx',
    );
  });
});

import { describe, expect, it } from 'vitest';
import {
  mapPagefindResults,
  normalizePagefindUrl,
  sanitizePagefindExcerpt,
} from '@/lib/search/providers/pagefind';

describe('sanitizePagefindExcerpt', () => {
  it('keeps mark tags and removes other markup', () => {
    expect(sanitizePagefindExcerpt('Install the <mark>tracker</mark> script.')).toBe(
      'Install the <mark>tracker</mark> script.',
    );
    expect(sanitizePagefindExcerpt('<p>Some <b>bold</b> text</p>')).toBe('Some bold text');
    expect(sanitizePagefindExcerpt('<p>A <mark>match</mark> inside</p>')).toBe(
      'A <mark>match</mark> inside',
    );
  });

  it('decodes basic HTML entities', () => {
    expect(sanitizePagefindExcerpt('Tom &amp; Jerry &lt;3 &quot;quotes&quot; &#39;here&#39;')).toBe(
      'Tom & Jerry <3 "quotes" \'here\'',
    );
  });
});

describe('normalizePagefindUrl', () => {
  it('strips index.html and trailing slashes', () => {
    expect(normalizePagefindUrl('/docs/foo/index.html')).toBe('/docs/foo');
    expect(normalizePagefindUrl('/docs/foo/')).toBe('/docs/foo');
    expect(normalizePagefindUrl('/docs/foo')).toBe('/docs/foo');
  });

  it('preserves anchors', () => {
    expect(normalizePagefindUrl('/docs/foo/index.html#setup')).toBe('/docs/foo#setup');
    expect(normalizePagefindUrl('/docs/foo/#setup')).toBe('/docs/foo#setup');
  });

  it('keeps the root path', () => {
    expect(normalizePagefindUrl('/')).toBe('/');
    expect(normalizePagefindUrl('/index.html')).toBe('/');
  });
});

describe('mapPagefindResults', () => {
  const fragment = {
    url: '/docs/install/index.html',
    excerpt: 'Page <mark>excerpt</mark>',
    meta: { title: 'Installation' },
    sub_results: [
      { title: 'Installation', url: '/docs/install/', excerpt: 'Intro <mark>text</mark>' },
      { title: 'Requirements', url: '/docs/install/#requirements', excerpt: 'Node 20+' },
      { title: 'Requirements', url: '/docs/install/index.html#requirements', excerpt: 'Dup' },
    ],
  };

  it('expands sub-results into individual results', () => {
    const results = mapPagefindResults([{ fragment, score: 2.5 }], 10);

    expect(results).toEqual([
      {
        url: '/docs/install',
        page: 'Installation',
        heading: undefined,
        snippet: 'Intro <mark>text</mark>',
        score: 2.5,
      },
      {
        url: '/docs/install#requirements',
        page: 'Installation',
        heading: 'Requirements',
        snippet: 'Node 20+',
        score: 2.5,
      },
    ]);
  });

  it('omits the heading when it matches the page title or has no anchor', () => {
    const results = mapPagefindResults([{ fragment }], 10);

    expect(results[0].heading).toBeUndefined();
    expect(results[1].heading).toBe('Requirements');
  });

  it('de-dupes results by normalized url', () => {
    const results = mapPagefindResults([{ fragment }], 10);

    expect(results.map(result => result.url)).toEqual([
      '/docs/install',
      '/docs/install#requirements',
    ]);
  });

  it('enforces the limit', () => {
    expect(mapPagefindResults([{ fragment }], 1)).toHaveLength(1);
  });

  it('defaults missing scores to 0 and falls back to the page fragment', () => {
    const bare = { url: '/docs/faq/', meta: { title: 'FAQ' }, excerpt: 'An <mark>answer</mark>' };
    const results = mapPagefindResults([{ fragment: bare }], 10);

    expect(results).toEqual([
      {
        url: '/docs/faq',
        page: 'FAQ',
        heading: undefined,
        snippet: 'An <mark>answer</mark>',
        score: 0,
      },
    ]);
  });
});

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';
import { OpenApiOperation } from '@/components/OpenApiOperation';
import { OpenApiSchema } from '@/components/OpenApiSchema';
import {
  methodBadgeText,
  methodColor,
  normalizeOperationKey,
  operationSections,
  schemaSections,
  statusColor,
} from '@/lib/openapi';
import type { NormalizedOperation, SchemaPage } from '@/lib/types';

const operation: NormalizedOperation = {
  id: 'create-user',
  key: 'POST /users',
  method: 'POST',
  path: '/users',
  summary: 'Create a user',
  tags: ['Users'],
  parameters: {
    query: [],
    path: [{ name: 'id', type: 'string', required: true, description: 'User identifier.' }],
    header: [],
    cookie: [],
  },
  requestBody: {
    required: true,
    contentType: 'application/json',
    schema: {
      type: 'object',
      children: [
        { name: 'name', type: 'string', required: true },
        {
          name: 'status',
          type: 'enum<string>',
          enum: ['active', 'disabled'],
        },
        {
          name: 'address',
          type: 'object',
          children: [{ name: 'city', type: 'string' }],
        },
      ],
    },
    example: '{\n  "name": "Ada"\n}',
  },
  responses: [
    { status: '201', description: 'Created.', example: '{\n  "id": "1"\n}' },
    { status: '404', description: 'Missing.' },
  ],
  security: [
    { name: 'bearerAuth', type: 'http', scheme: 'bearer', label: 'bearerAuth (http bearer)' },
  ],
  servers: [{ url: 'https://api.demo.dev' }],
  serverUrl: 'https://api.demo.dev',
  samples: [
    { language: 'bash', label: 'cURL', source: "curl -X POST 'https://api.demo.dev/users'" },
    { language: 'python', label: 'Python', source: 'import requests' },
  ],
};

describe('operationSections', () => {
  it('produces stable heading ids in render order', () => {
    expect(operationSections(operation)).toEqual([
      { name: 'Headers', id: 'headers', size: 2 },
      { name: 'Path parameters', id: 'path-parameters', size: 2 },
      { name: 'Request body', id: 'request-body', size: 2 },
      { name: 'Responses', id: 'responses', size: 2 },
      { name: 'Code samples', id: 'code-samples', size: 2 },
    ]);
  });

  it('prepends the playground section when enabled', () => {
    expect(operationSections(operation, undefined, { playground: true })[0]).toEqual({
      name: 'Try it',
      id: 'try-it',
      size: 2,
    });
  });

  it('omits sections without content', () => {
    const bare: NormalizedOperation = {
      ...operation,
      parameters: { query: [], path: [], header: [], cookie: [] },
      security: [],
      requestBody: undefined,
      samples: [],
    };
    expect(operationSections(bare).map(entry => entry.id)).toEqual(['responses']);
  });
});

describe('color maps', () => {
  it('maps methods and statuses to badge colors', () => {
    expect(methodColor('GET')).toBe('green');
    expect(methodColor('delete')).toBe('red');
    expect(methodColor('CUSTOM')).toBe('gray');
    expect(statusColor('201')).toBe('green');
    expect(statusColor('404')).toBe('red');
  });
});

describe('OpenApiOperation', () => {
  const html = renderToStaticMarkup(<OpenApiOperation operation={operation} />);

  it('renders all sections with anchor ids', () => {
    expect(html).toContain('id="headers"');
    expect(html).toContain('id="path-parameters"');
    expect(html).toContain('id="request-body"');
    expect(html).toContain('id="responses"');
    expect(html).toContain('id="code-samples"');
  });

  it('renders parameters including the auth header', () => {
    expect(html).toContain('Authorization');
    expect(html).toContain('Authentication credentials');
    expect(html).toContain('Bearer &lt;token&gt;');
    expect(html).toContain('User identifier.');
    expect(html).not.toContain('id="try-it"');
  });

  it('describes API keys where they are sent', () => {
    const keyed = renderToStaticMarkup(
      <OpenApiOperation
        operation={{
          ...operation,
          security: [
            { name: 'key', type: 'apiKey', in: 'query', paramName: 'api_key', label: 'key' },
          ],
        }}
      />,
    );
    const query = keyed
      .split('<section>')
      .find(section => section.includes('id="query-parameters"'));
    expect(query).toContain('api_key');
    expect(query).toContain('&lt;api-key&gt;');
    expect(keyed).not.toContain('id="headers"');
  });

  it('renders the playground form ahead of the reference when enabled', () => {
    const withPlayground = renderToStaticMarkup(
      <OpenApiOperation operation={operation} playground={{}} />,
    );
    expect(withPlayground.indexOf('id="try-it"')).toBeLessThan(
      withPlayground.indexOf('id="headers"'),
    );
    expect(withPlayground).toContain('data-slot="api-playground"');
    expect(withPlayground).toContain('value="https://api.demo.dev"');
    expect(withPlayground).toContain('Send request');
    expect(withPlayground).toContain('type="password"');
    expect(withPlayground).toContain('<textarea');
    expect(withPlayground).toContain('curl -X POST');
  });

  it('keeps parameter locations in separate tables and preserves field details', () => {
    const grouped = renderToStaticMarkup(
      <OpenApiOperation
        operation={{
          ...operation,
          parameters: {
            ...operation.parameters,
            query: [{ name: 'limit', type: 'integer', default: '20', description: 'Page size.' }],
            cookie: [{ name: 'session', type: 'string', deprecated: true }],
          },
        }}
      />,
    );
    const sections = grouped.split('<section>');
    const headers = sections.find(section => section.includes('id="headers"'));
    const path = sections.find(section => section.includes('id="path-parameters"'));
    const query = sections.find(section => section.includes('id="query-parameters"'));
    const cookie = sections.find(section => section.includes('id="cookie-parameters"'));
    for (const section of [headers, path, query, cookie]) {
      expect(section).toContain('<table');
      expect(section).toContain('>Name</th>');
      expect(section).toContain('>Type</th>');
      expect(section).toContain('>Description</th>');
    }
    expect(headers).toContain('Authorization');
    expect(headers).not.toContain('User identifier.');
    expect(path).toContain('User identifier.');
    expect(path).not.toContain('Page size.');
    expect(query).toContain('Page size.');
    expect(query).toContain('Default: 20');
    expect(cookie).toContain('deprecated');
  });

  it('renders response schemas as tables, including primitive responses', () => {
    const responseHtml = renderToStaticMarkup(
      <OpenApiOperation
        operation={{
          ...operation,
          responses: [
            {
              status: '200',
              schema: {
                type: 'object',
                children: [{ name: 'id', type: 'string', required: true, description: 'User ID.' }],
              },
            },
            { status: '202', schema: { type: 'string', description: 'Pending.' } },
          ],
        }}
      />,
    ).split('id="responses"')[1];
    expect(responseHtml.match(/<table /g)).toHaveLength(2);
    expect(responseHtml).toContain('User ID.');
    expect(responseHtml).toContain('Pending.');
    expect(responseHtml).toContain('required');
  });

  it('puts nested properties in a full-width row below their parent', () => {
    expect(html).toMatch(/<\/tr><tr><td colSpan="3"[^>]*>/);
    expect(html).not.toContain('min-w-[40rem]');
  });

  it('labels complex alternatives as allowed types, including root unions', () => {
    const unionHtml = renderToStaticMarkup(
      <OpenApiOperation
        operation={{
          ...operation,
          responses: [
            {
              status: '200',
              schema: {
                type: 'anyOf',
                children: [
                  { name: 'option 1', type: 'object', children: [{ name: 'id', type: 'string' }] },
                ],
              },
            },
          ],
        }}
      />,
    ).split('id="responses"')[1];
    expect(unionHtml).toContain('anyOf');
    expect(unionHtml).toContain('Allowed types');
    expect(unionHtml).toContain('colSpan="3"');
  });

  it('renders nested schema fields inside an expandable', () => {
    expect(html).toContain('name');
    expect(html).toContain('properties');
    expect(html).toContain('city');
    expect(html).toContain('<code>active</code>');
  });

  it('renders responses with status badges and examples', () => {
    expect(html).toContain('201');
    expect(html).toContain('Created.');
    expect(html).toContain('201 example');
  });

  it('renders unhighlighted sample fallbacks inside a code group', () => {
    expect(html).toContain('curl -X POST');
    expect(html).toContain('class="language-bash"');
  });

  it('labels sample tabs with their language names', () => {
    expect(html).toContain('>cURL</button>');
    expect(html).toContain('>Python</button>');
    // The tab list keeps its "Code snippets" aria-label; only the fallback
    // "snippet N" tab labels must never appear.
    expect(html).not.toContain('snippet 1');
  });
});

describe('webhooks and schema pages', () => {
  const webhook: NormalizedOperation = {
    ...operation,
    key: 'WEBHOOK userCreated',
    webhook: true,
    path: 'userCreated',
    parameters: { query: [], path: [], header: [], cookie: [] },
    security: [],
    servers: [],
    serverUrl: '',
    samples: [],
  };

  it('renders webhooks with a payload section and never a playground', () => {
    expect(operationSections(webhook, undefined, { playground: true }).map(entry => entry.id)).toEqual(
      ['payload', 'responses'],
    );
    const html = renderToStaticMarkup(<OpenApiOperation operation={webhook} playground={{}} />);
    expect(html).toContain('id="payload"');
    expect(html).toContain('>Payload<');
    expect(html).not.toContain('id="try-it"');
    expect(html).not.toContain('id="code-samples"');
  });

  it('normalizes frontmatter keys like the build scripts', () => {
    expect(normalizeOperationKey('get /users')).toBe('GET /users');
    expect(normalizeOperationKey('Webhook userCreated')).toBe('WEBHOOK userCreated');
    expect(normalizeOperationKey('users.yaml get /users')).toBe('users.yaml GET /users');
    expect(normalizeOperationKey('User')).toBeUndefined();
    expect(methodBadgeText('WEBHOOK')).toBe('HOOK');
    expect(methodColor('WEBHOOK')).toBe('yellow');
  });

  it('renders schema pages with properties and an example', () => {
    const page: SchemaPage = {
      name: 'User',
      key: 'User',
      description: 'A user.',
      schema: {
        type: 'object',
        children: [
          { name: 'id', type: 'string', required: true },
          { name: 'address', type: 'object', children: [{ name: 'city', type: 'string' }] },
        ],
      },
      example: '{\n  "id": "1"\n}',
    };
    expect(schemaSections(page).map(entry => entry.id)).toEqual(['properties', 'example']);
    const html = renderToStaticMarkup(<OpenApiSchema page={page} />);
    expect(html).toContain('id="properties"');
    expect(html).toContain('id="example"');
    expect(html).toContain('>id<');
    expect(html).toContain('&quot;id&quot;: &quot;1&quot;');
    expect(renderToStaticMarkup(<OpenApiSchema page={{ ...page, example: undefined }} />)).not.toContain(
      'id="example"',
    );
  });
});

import { describe, expect, it } from 'vitest';
import { filterRecordsByScope, type SearchRecord, searchIndex } from '@/lib/search';

const records: SearchRecord[] = [
  { url: '/docs', page: 'Overview', text: 'Shiso is a static docs generator.' },
  {
    url: '/docs/configuration',
    page: 'Configuration',
    heading: 'Redirects',
    id: 'redirects',
    text: 'The redirects key maps moved pages to new locations.',
  },
  {
    url: '/docs/configuration',
    page: 'Configuration',
    heading: 'Fonts',
    id: 'fonts',
    text: 'Google Fonts families load automatically.',
  },
];

describe('searchIndex', () => {
  it('returns nothing for an empty query', () => {
    expect(searchIndex(records, '')).toEqual([]);
    expect(searchIndex(records, '   ')).toEqual([]);
  });

  it('matches page titles ahead of body text', () => {
    const results = searchIndex(records, 'configuration');

    expect(results[0].page).toBe('Configuration');
  });

  it('appends the heading anchor to result urls', () => {
    const results = searchIndex(records, 'redirects');

    expect(results[0].url).toBe('/docs/configuration#redirects');
  });

  it('requires every term to match', () => {
    expect(searchIndex(records, 'google automatically')).toHaveLength(1);
    expect(searchIndex(records, 'google zebra')).toHaveLength(0);
  });

  it('builds a snippet around body matches with the match highlighted', () => {
    const results = searchIndex(records, 'moved');

    expect(results[0].snippet).toContain('<mark>moved</mark> pages');
  });

  it('highlights every matching term in the snippet', () => {
    const results = searchIndex(records, 'google automatically');

    expect(results[0].snippet).toBe(
      '<mark>Google</mark> Fonts families load <mark>automatically</mark>.',
    );
  });

  it('respects the limit', () => {
    expect(searchIndex(records, 'docs', 1)).toHaveLength(1);
  });
});

describe('filterRecordsByScope', () => {
  const scoped: SearchRecord[] = [
    {
      url: '/docs/v1',
      page: 'V1 Overview',
      text: 'Legacy setup guide.',
      scopeId: 'v1',
      version: 'v1',
    },
    {
      url: '/docs/v2',
      page: 'V2 Overview',
      text: 'Current setup guide.',
      scopeId: 'v2',
      version: 'v2',
    },
    { url: '/docs/shared', page: 'Shared', text: 'Unscoped record.' },
  ];

  it('returns everything without a scope context', () => {
    expect(filterRecordsByScope(scoped)).toEqual(scoped);
    expect(filterRecordsByScope(scoped, {})).toEqual(scoped);
  });

  it('keeps only the active scope plus unscoped records', () => {
    const filtered = filterRecordsByScope(scoped, { scopeId: 'v1' });

    expect(filtered.map(record => record.url)).toEqual(['/docs/v1', '/docs/shared']);
  });

  it('does not mix versions in search results', () => {
    const results = searchIndex(filterRecordsByScope(scoped, { scopeId: 'v2' }), 'setup');

    expect(results.map(result => result.url)).toEqual(['/docs/v2']);
  });
});

